'use strict';
const roleNames={viewer:'一般員工',warehouse:'庫房管理',supervisor:'主管'};
const roleDescriptions={viewer:'只能查看案件、庫存與照片',warehouse:'只能收料、領料及上傳照片',supervisor:'全區開放，可管理員工、案件、庫房、資訊庫與網站設定'};
let employeesCache=[];
function applyRoleUI(){
 const role=currentUser.role,label=roleNames[role]||'未授權',header=$('.header-actions');
 if(header&&!$('#current-role')){const badge=document.createElement('span');badge.id='current-role';badge.className='role-badge role-'+role;badge.textContent=(currentUser.name||'使用者')+' · '+label;header.prepend(badge);}
 if(header&&!$('#account-actions')){const wrap=document.createElement('span');wrap.id='account-actions';wrap.innerHTML='<button type="button" class="small" id="change-password">修改密碼</button> <button type="button" class="small" id="logout">登出</button>';header.append(wrap);$('#change-password').onclick=passwordDialog;$('#logout').onclick=logout;}
 if(role==='supervisor')return;
 for(const selector of ['#edit-site','#new-project','#deleted-projects','#new-case','#export-cases','#export-warehouse','[data-case-status]','[data-case-edit]','[data-case-up]','[data-case-down]','[data-project-up]','[data-project-down]','.project-order-controls','#rename-project','#delete-project','#import-bom','#add-part','#restore-part','[data-remove]','#save-custom','.audit-fold','#content-admin'])document.querySelectorAll(selector).forEach(el=>el.remove());
 document.querySelectorAll('.name-input,.spec-input,.demand-input,.sets-input,.location-input input,.location-input select,#receipt-form input[name="basketCount"],#receipt-form .admin-card input').forEach(el=>el.readOnly=true);
 document.querySelectorAll('.location-input select').forEach(el=>el.disabled=true);
 document.querySelectorAll('#receipt-form .admin-card select').forEach(el=>el.disabled=true);
 if(role==='viewer'){document.querySelectorAll('#receipt-form input,#receipt-form select').forEach(el=>{if(el.type!=='hidden')el.disabled=true;});document.querySelectorAll('#receipt-form button[type="submit"],#upload-receipts,#receipt-files').forEach(el=>el.remove());}
}
function roleCard(role){return '<div class="role-card role-'+role+'"><strong>'+roleNames[role]+'</strong><p>'+roleDescriptions[role]+'</p></div>';}
async function loadEmployees(){
 const box=$('#employee-list');if(!box)return;
 try{
  const r=await apiFetch('/api/employees'),data=await r.json();if(!r.ok)throw Error(data.error||'無法載入員工');employeesCache=data.items||[];
  box.innerHTML=employeesCache.map(e=>`<div class="employee-row"><div><strong>${esc(e.name)}</strong><small>${esc(e.email)}</small></div><span class="role-badge role-${esc(e.role)}">${esc(roleNames[e.role])}</span><span class="employee-state ${e.status==='active'?'active':''}">${e.status==='active'?'啟用':'停用'}</span><small>${e.account_user_id?(e.last_login_at?'最後登入 '+esc(receiptTime(e.last_login_at)):'已寄送邀請，等待首次登入'):'尚未建立登入帳號'}</small><button type="button" data-edit-employee="${e.id}">修改</button>${e.id===data.currentEmployeeId?'':`<button type="button" class="danger-button" data-delete-employee="${e.id}">刪除</button>`}</div>`).join('')||'<div class="empty">尚未建立員工</div>';
  document.querySelectorAll('[data-edit-employee]').forEach(el=>el.onclick=()=>employeeDialog(Number(el.dataset.editEmployee)));document.querySelectorAll('[data-delete-employee]').forEach(el=>el.onclick=()=>deleteEmployee(Number(el.dataset.deleteEmployee)));
 }catch(e){box.innerHTML='<p class="error">'+esc(e.message)+'</p>';}
}
function enhanceEmployeesAdmin(){
 const main=$('main');if(!main||$('#employee-admin')||currentUser.role!=='supervisor')return;
 const card=document.createElement('section');card.id='employee-admin';card.className='admin-card employee-admin';card.innerHTML='<div class="employee-title"><div><h2>員工與權限</h2><p>三種層級一目瞭然；停用帳號會立即失去系統權限。</p></div><button type="button" id="new-employee" class="primary">＋ 邀請員工</button></div><div class="role-grid">'+roleCard('viewer')+roleCard('warehouse')+roleCard('supervisor')+'</div><div class="notice">主管填寫員工信箱與權限後，系統會寄出邀請信。員工點開連結自行設定密碼，不需要 ChatGPT 或 Cloudflare 帳號。</div><div id="employee-list">正在載入員工…</div>';const first=main.querySelector('.admin-card');if(first)first.before(card);else main.append(card);$('#new-employee').onclick=()=>employeeDialog();loadEmployees();
}
function employeeDialog(id){
 const existing=employeesCache.find(e=>e.id===id)||{name:'',email:'',role:'viewer',status:'active'};
 modal(id?'修改員工':'邀請員工',field('員工姓名','name',existing.name,'required maxlength="80"')+field('登入信箱','email',existing.email,'type="email" required maxlength="200"')+(id?'':'<div class="notice">送出後系統會寄送邀請信，由員工自行設定密碼。</div>')+'<div class="form-grid"><label class="field">權限層級<select name="role">'+Object.entries(roleNames).map(([v,l])=>'<option value="'+v+'" '+(existing.role===v?'selected':'')+'>'+l+'</option>').join('')+'</select></label><label class="field">帳號狀態<select name="status"><option value="active" '+(existing.status==='active'?'selected':'')+'>啟用</option><option value="disabled" '+(existing.status==='disabled'?'selected':'')+'>停用</option></select></label></div><div class="notice" id="role-help">'+esc(roleDescriptions[existing.role])+'</div>',id?'儲存員工':'寄送邀請',async fd=>{const payload={id,name:String(fd.get('name')||'').trim(),email:String(fd.get('email')||'').trim(),role:String(fd.get('role')),status:String(fd.get('status'))},r=await apiFetch('/api/employees',{method:id?'PUT':'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)}),data=await r.json();if(!r.ok)error(data.error||'員工設定未完成');addAudit(id?'修改員工權限':'邀請員工帳號',payload.name+' · '+roleNames[payload.role],'管理後台 > 員工與權限');persist();$('#modal').close();renderAdmin();toast(id?'員工資料已更新':'邀請信已寄出，員工可自行設定密碼');});const select=$('#modal select[name="role"]');select.onchange=()=>{$('#role-help').textContent=roleDescriptions[select.value];};
}
async function deleteEmployee(id){const e=employeesCache.find(x=>x.id===id);if(!e||!confirm('確定刪除員工「'+e.name+'」？此員工將失去系統權限。'))return;try{const r=await apiFetch('/api/employees',{method:'DELETE',headers:{'Content-Type':'application/json'},body:JSON.stringify(e)}),data=await r.json();if(!r.ok)throw Error(data.error||'無法刪除員工');addAudit('刪除員工帳號',e.name,'管理後台 > 員工與權限');persist();renderAdmin();toast('員工已刪除');}catch(err){toast(err.message);}}
function passwordDialog(){modal('修改登入密碼',field('新密碼','password','','type="password" minlength="8" required autocomplete="new-password"')+field('再次輸入新密碼','confirm','','type="password" minlength="8" required autocomplete="new-password"')+'<small>密碼至少 8 碼，需包含英文字母與數字。</small>','更新密碼',async fd=>{const password=String(fd.get('password')||''),confirmPassword=String(fd.get('confirm')||'');if(password!==confirmPassword)error('兩次輸入的密碼不同。');if(password.length<8||!/[A-Za-z]/.test(password)||!/\d/.test(password))error('密碼至少 8 碼，需包含英文字母與數字。');const cfg=await getAuthConfig(),session=await authSession(),r=await fetch(cfg.url+'/auth/v1/user',{method:'PUT',headers:{apikey:cfg.publishableKey,Authorization:'Bearer '+session.access_token,'Content-Type':'application/json'},body:JSON.stringify({password})}),data=await r.json();if(!r.ok)error(data.message||'密碼更新失敗');$('#modal').close();toast('密碼已更新');});}
const renderBeforeRoles=render;render=function(){renderBeforeRoles();applyRoleUI();};
function makeAdminCardsCollapsible(){document.querySelectorAll('section.admin-card').forEach(card=>{const title=card.querySelector('h2')?.textContent||'設定';const details=document.createElement('details');details.className=card.className;details.id=card.id;details.innerHTML='<summary><h2>'+esc(title)+'</h2><span>展開／收合</span></summary><div class="admin-card-body"></div>';card.querySelector('h2')?.remove();while(card.firstChild)details.querySelector('.admin-card-body').append(card.firstChild);card.replaceWith(details);});}
const renderAdminBeforeRoles=renderAdmin;renderAdmin=function(){if(currentUser.role!=='supervisor'){history.replaceState(null,'',location.pathname);render();toast('只有主管可以進入管理後台');return;}renderAdminBeforeRoles();enhanceEmployeesAdmin();makeAdminCardsCollapsible();applyRoleUI();};
const renderContentBeforeRoles=renderContent;renderContent=function(...args){renderContentBeforeRoles(...args);applyRoleUI();};
